from lib import *
S = SS('w13')
steps = [
    step("TTL 的默认值:sysctl net.inet.ip.ttl = 64,TCP 和 UDP 套接字上 getsockopt(IP_TTL) 读到的也是 64,setsockopt 设成 7 以后读回 7。给本机 127.0.0.1 发 TTL=1 的 UDP 包,对方照样收到,抓到的包 TTL 仍是 1——没经过路由器就不会被减。往公网地址 ping 时用 -m 限制 TTL:-m 1 由第 1 跳(本机局域网网关)回 “Time to live exceeded”,-m 2、-m 3 分别由第 2、第 3 跳(都是私有地址的路由器)回;ping -m 1 默认网关则收到应答,因为网关就是目的地,不需要再转发。", t=tl(S(1)), mark=lidx(S(1), 'ping -m 1 到公网', 'ping -m 2 到公网', 'ping -m 3 到公网'), done=lidx(S(1), 'net.inet.ip.ttl', '默认 = 64', 'TTL=1 的 UDP 包', '默认网关'), kv=KV([['默认 TTL', '64(sysctl 与套接字一致)'], ['IP_TTL', 'setsockopt 可改,读回 7'], ['发给本机', 'TTL=1 照样送达,不被减'], ['路由器转发', 'TTL 减 1,到 0 就丢并回 ICMP']], ['路由器转发'])),
    step("系统 traceroute(每跳 3 个探测)到一个公网地址,15 跳到达目的地:第 1 跳是本机局域网网关,第 2、3 跳是私有地址,第 4 跳起是公网地址。RTT 随跳数增大——第 2、3 跳约 3 ms,第 8 跳起约 40~60 ms,第 13 跳 182.9 ms、第 15 跳 194.9 ms。第 5、14 跳三个探测全部无应答(* * *);很多跳只收到 3 个里的 1~2 个;有 6 个跳(6、8、9、10、12、15)的探测来自不止一个地址——同一跳的几个探测走了不同的路由器(多路径)。最大 RTT 237.2 ms。", t=tl(S(2)), mark=lidx(S(2), '(* * *)', '不同地址  RTT 39.2', '来自 3 个不同地址'), done=lidx(S(2), '第  1 跳', '第  2 跳', '第  4 跳', '第 15 跳', '目的地在第'), b=bars([['第 2 跳 最小 RTT', 2.7, '2.7 ms'], ['第 4 跳', 4.5, '4.5 ms'], ['第 8 跳', 39.2, '39.2 ms'], ['第 11 跳', 49.8, '49.8 ms'], ['第 13 跳', 182.9, '182.9 ms'], ['第 15 跳(目的地)', 194.9, '194.9 ms']], 200, mark=[4, 5], done=[0, 1, 2, 3]), kv=KV([['无应答的跳', '2 个(第 5、14 跳)'], ['多地址的跳', '6 个:同一跳不同探测走不同路由器'], ['到达目的地', '第 15 跳']], ['多地址的跳'])),
    step("抓包看 traceroute 到底发了什么:UDP 探测包 TTL 依次是 1、2、3…,目的端口从 33435 开始每个加 1,源端口不变,IP 总长 40 字节(UDP 长度 20,载荷 12 字节)。路由器把 TTL 减到 0 时丢弃它,回 ICMP 类型 11/代码 0(Time Exceeded),里面引用的原包里 TTL 都是 1、目的端口就是对应探测的端口——traceroute 靠引用的端口把回复对到探测上。这次共发 16 个探测:10 个 Time Exceeded,1 个 3/3(端口不可达,来自目的地本身,TTL=16 时包到了目的地),5 个无回复(TTL 5、6、7、9、13)。回复包自己的 TTL:前三跳是 64、63、62,后面是 252、248、245 等接近 255 的值。RTT 从 2.6 ms 涨到 199.4 ms。", t=tl(S(3)), mark=lidx(S(3), '3/3', '无回复'), done=lidx(S(3), '11/0', '目的端口从', 'Time Exceeded 10 个', '回复包自己的 TTL'), b=bars([['Time Exceeded (11/0)', 10, '10'], ['端口不可达 (3/3)', 1, '1'], ['无回复', 5, '5']], 16, mark=[2], done=[0, 1]), kv=KV([['探测', 'UDP,TTL 递增,端口 33435 起逐个 +1'], ['中间路由器', 'ICMP 11/0,引用原包头'], ['目的地', 'ICMP 3/3 端口不可达 → 到了'], ['引用的端口', '用来对应哪个探测']], ['引用的端口'])),
    step("自己实现 traceroute:UDP 套接字设 IP_TTL=1~20 发探测(没有原始套接字权限,ICMP 回复从抓包里读)。同样 20 个探测,目的端口从 33435 起、间隔 40 ms 收到 15 个回复(6 个来自目的地);间隔 250 ms 收到 15 个(5 个来自目的地);间隔 1000 ms 收到 18 个(6 个来自目的地);目的端口换成从 34500 起、间隔 250 ms,只收到 6 个、0 个来自目的地——端口范围不同回复数差很多,原因没有验证。取回复最多的一轮(33435 起、间隔 1000 ms)和系统 traceroute(-q 1)逐跳对比:两边都有应答的跳里地址相同 8 个、不同 4 个(同一跳可以是不同的路由器)。无应答的第 6、7 跳再各发 8 个探测:TTL=6 收到 3/8,TTL=7 收到 0/8——“*” 只表示这次没收到回复,不一定是路由器不存在。", t=tl(S(4)), mark=lidx(S(4), '从 34500 起', '地址相同 8 个'), done=lidx(S(4), '间隔 40 ms 发', '间隔 250 ms 发 TTL', '间隔 1000 ms 发', '那一轮里无应答'), b=bars([['33435 起 · 间隔 40 ms', 15, '15 / 20'], ['33435 起 · 间隔 250 ms', 15, '15 / 20'], ['33435 起 · 间隔 1000 ms', 18, '18 / 20'], ['34500 起 · 间隔 250 ms', 6, '6 / 20']], 20, mark=[3], done=[0, 1, 2]), kv=KV([['IP_TTL 递增', '不用原始套接字也能发探测'], ['超过路径长度的 TTL', '都从目的地得到端口不可达'], ['端口 34500 起', '回复明显变少,原因没验证'], ['*', '只表示这次没收到']], ['*'])),
    step("不用 traceroute 也能估跳数:收到的包的 TTL 向上取最近的常见初始值(32 / 64 / 128 / 255),初始值 − TTL + 1 就是估计的跳数。试了 5 个公网目的地,TCP 能连通 4 个,SYN-ACK 的 TTL 是 48、51、51、51,初始值都推成 64,估计 17、14、14、14 跳;traceroute 实测到达的是 15、14、13、未到达。估计与实测相同的只有 1 / 4 个,差值 2、0、1——回程路径可以和去程不同,估计只能当参考。再用 IP_TTL=n 去 connect 目的地 1:n=15 是第一次成功的,与 traceroute 的第 15 跳吻合;目的地 2 的第一次成功是 n=14,traceroute 也是第 14 跳。n 太小时 connect 都失败:n=1、2、3 是 No route to host(65),n=4 起是超时(EAGAIN 35)——目的地 2 的 n=10 也出现了 65;两类错误与 ICMP 回复的对应关系没有逐一验证。", t=tl(S(5)), mark=lidx(S(5), '估计与实测相同', 'n=15 是第一次成功', 'n=14 是第一次成功'), done=lidx(S(5), '目的地1', '目的地2', '目的地3', '目的地4', '试了 5 个'), b=bars([['目的地1 估计', 17, '17'], ['目的地1 实测', 15, '15'], ['目的地2 估计', 14, '14'], ['目的地2 实测', 14, '14'], ['目的地3 估计', 14, '14'], ['目的地3 实测', 13, '13']], 17, mark=[0, 1], done=[2, 3, 4, 5]), kv=KV([['估计公式', '初始值 − 收到的 TTL + 1'], ['估计 = 实测', '1 / 4 个,差 0~2'], ['最小可连通 TTL', '与 traceroute 到达跳数吻合(15、14)'], ['TTL 不够', 'connect 失败:65 或超时']], ['最小可连通 TTL'])),
]
A = mkartw('w13', 13, '网络协议,TTL,traceroute,ICMP,Time Exceeded,跳数,真实验证,动画演示',
    '默认 TTL 64;抓包看 traceroute:UDP 探测 TTL 递增、端口 33435 起逐个加 1,路由器回 ICMP 11/0 并引用原包,目的地回 3/3;15 跳里 2 个全无应答、6 个多路径;自己用 IP_TTL 实现 traceroute;收到包的 TTL 估跳数与实测差 0~2。',
    'TTL 到底是怎么变成“traceroute 的每一跳”的?为什么有的跳显示 * * *,同一跳还会出现几个不同的地址?这篇在真实公网路径上抓包,逐个看探测包、路由器回的 ICMP,再自己用 IP_TTL 写一个 traceroute,最后用收到的包的 TTL 估算跳数并和实测对比。',
    [('15 跳', '到一个公网地址的系统 traceroute 结果:第 5、14 跳全无应答,6 个跳出现多个地址'), ('11/0 与 3/3', '中间路由器回 ICMP Time Exceeded,目的地回端口不可达;引用的原包里 TTL 都是 1'), ('15 / 20 对 6 / 20', '同样 20 个探测:目的端口从 33435 起收到 15 个回复,从 34500 起只有 6 个')],
    [('TTL 是什么', '<p>TTL 是 IP 头里 1 字节的生存时间,每过一个路由器减 1,到 0 就丢弃并回 ICMP Time Exceeded。系统默认 64,套接字上可用 IP_TTL 读写;发给本机不经路由器,所以不会被减。</p>'),
     ('traceroute 的输出', '<p>每跳通常发 3 个探测,看到的是该跳的地址和 RTT。实测 15 跳里有 2 跳全无应答、6 跳的探测来自多个地址(路径上有多条并行链路),RTT 随跳数增大。</p>'),
     ('线上的样子', '<p>探测是 UDP 包,TTL 递增,目的端口从 33435 起逐个加 1;中间路由器回 ICMP 11/0 并引用原包头(其中的端口用来对应探测),目的地因为没人监听该端口回 3/3 端口不可达,traceroute 就知道到了。</p>'),
     ('自己实现', '<p>设 IP_TTL 发 UDP 探测就能做 traceroute,回复要读 ICMP(没有原始套接字权限时从抓包里读)。探测间隔和目的端口都影响收到的回复数,无应答的跳多发几次有时能收到。</p>'),
     ('用 TTL 估跳数', '<p>收到的包的 TTL 向上取到常见初始值,初始值 − TTL + 1 约等于跳数,实测与 traceroute 差 0~2;把 TCP 连接的 IP_TTL 从 1 往上试,第一次能连通的值与 traceroute 到达的跳数吻合。</p>')],
    steps,
    [ENV_W + '。公网路径上别人的路由器地址一律不写出来,只记类别与 RTT;每次重跑路径与应答的跳都会略有不同,文中数字来自最后一次运行;自己实现的 traceroute 通过 tcpdump 抓包读取 ICMP 回复(没有原始套接字权限),不是读套接字',
     '没有验证:IPv6 的 Hop Limit 与 traceroute6;TCP / ICMP 方式的 traceroute(-T / -I);路由器不回 Time Exceeded 或限速的具体原因;为什么目的端口 34500 起收到的回复明显更少(可能与路径上按端口的转发选择或过滤有关,未证实);多路径的哈希依据;MPLS 对 traceroute 的影响;connect 错误码 65 与 35 的完整对应关系'],
    'TTL 与 traceroute')
